package com.quickcart.controller; import com.quickcart.service.CatalogService; import com.quickcart.entity.Category; import com.quickcart.dto.ProductResponse; import org.springframework.web.bind.annotation.*; import org.springframework.data.domain.*; import java.util.*;
@RestController @RequestMapping("/api/v1") public class CatalogController {final CatalogService s;CatalogController(CatalogService x){s=x;} @GetMapping("/categories") List<Category> categories(){return s.categories();} @GetMapping("/products") Page<ProductResponse> products(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="30")int size){return s.products(page,size);} @GetMapping("/products/{id}") ProductResponse one(@PathVariable Long id){return s.one(id);} @GetMapping("/products/category/{id}") List<ProductResponse> cat(@PathVariable Long id){return s.category(id);} @GetMapping("/products/search") List<ProductResponse> search(@RequestParam String query){return s.search(query);} }
